<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $base = App\Core\Config::url('/campeonatos/' . $championship['slug']); $initials = static function (string $name): string { $parts = preg_split('/\s+/', trim($name)) ?: []; $value = ''; foreach (array_slice($parts, 0, 2) as $part) { $value .= strtoupper(substr($part, 0, 1)); } return $value ?: 'AT'; }; $stats = $profile['stats'] ?? []; ?>
<section class="portal-page-heading athlete-profile"><?php if ($athlete['photo_path']): ?><img class="portal-athlete-photo portal-athlete-photo-large" src="<?= $e($base . '/atletas/' . $athlete['id'] . '/foto?v=' . rawurlencode((string) $athlete['photo_path'])) ?>" alt="Foto de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?php else: ?><span class="athlete-avatar-fallback portal-athlete-photo-large" aria-label="Avatar provisório de <?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?>"><?= $e($initials((string) ($athlete['sporting_name'] ?: $athlete['full_name']))) ?></span><?php endif; ?><p class="eyebrow"><?= $e($championship['name']) ?></p><h1><?= $e($athlete['sporting_name'] ?: $athlete['full_name']) ?></h1><p><?= $e($athlete['position_name']) ?> · <a href="<?= $e($base . '/equipes/' . rawurlencode($athlete['team_slug'])) ?>"><?= $e($athlete['team_name']) ?></a></p><?php if ($athlete['preferred_number']): ?><span class="portal-badge">Número <?= (int) $athlete['preferred_number'] ?></span><?php endif; ?></section>
<section class="athlete-profile-data"><div class="profile-facts"><article><span>Data de nascimento</span><strong><?= $e($athlete['birth_date'] ?: 'Não divulgada') ?></strong></article><article><span>Posição</span><strong><?= $e($athlete['position_name']) ?></strong></article><article><span>Equipe atual</span><strong><?= $e($athlete['team_name']) ?></strong></article></div><div class="club-stat-grid athlete-stat-grid"><?php foreach (['goals' => 'Gols', 'assists' => 'Assistências', 'yellows' => 'Amarelos', 'reds' => 'Vermelhos'] as $key => $label): ?><article><span><?= $label ?></span><strong><?= (int) ($stats[$key] ?? 0) ?></strong></article><?php endforeach; ?></div><div class="club-history-grid"><article class="panel"><h2>Títulos e colocações</h2><?php if (!empty($profile['honours'])): ?><ul class="honour-list"><?php foreach ($profile['honours'] as $honour): ?><li><strong><?= $e($honour['honour']) ?></strong><span><?= $e($honour['championship_name']) ?> · <?= $e($honour['season_name']) ?></span></li><?php endforeach; ?></ul><?php else: ?><p class="muted">Ainda não há títulos ou colocações finais registrados.</p><?php endif; ?></article><article class="panel"><h2>Equipes e transferências</h2><?php if (!empty($profile['teams'])): ?><ul class="honour-list"><?php foreach ($profile['teams'] as $team): ?><li><strong><?= $e($team['name']) ?></strong><span><?= $e($team['championship_name']) ?></span></li><?php endforeach; ?></ul><?php endif; ?><?php if (!empty($profile['transfers'])): ?><ul class="transfer-history"><?php foreach ($profile['transfers'] as $transfer): ?><li><?= $e($transfer['previous_team_name'] ?: 'Sem equipe') ?> <b>→</b> <?= $e($transfer['next_team_name'] ?: 'Sem equipe') ?><small><?= $e($transfer['movement_date']) ?></small></li><?php endforeach; ?></ul><?php endif; ?><?php if (empty($profile['teams']) && empty($profile['transfers'])): ?><p class="muted">Histórico de equipes em atualização.</p><?php endif; ?></article></div></section>
